const main=document.querySelector('#main');
const state={role:sessionStorage.getItem('likeTacRole')||'visitor',returnTo:null,theme:localStorage.getItem('likeTacTheme')||'light'};
const episodes=[
 {id:'expressway-start',topic:'Deploying & Configuring Expressway',date:'2026-10-24',title:'Expressway without the acronym soup',desc:'What Expressway does, where it sits, and why anyone should care—explained with a front-door analogy.',access:'free',duration:'28 min'},
 {id:'traversal',topic:'Deploying & Configuring Expressway',date:'2026-10-17',title:'Traversal zones without tears',desc:'A plain-language walkthrough of the choices that usually make people reach for more coffee.',access:'member',duration:'41 min'},
 {id:'certs',topic:'Deploying & Configuring Expressway',date:'2026-10-03',title:'Certificates, DNS, and the usual suspects',desc:'The first places to look when a deployment seems correct but refuses to cooperate.',access:'member',duration:'36 min'},
 {id:'ai-latest',topic:'AI for Everyday Work',date:'2026-10-26',title:'AI: useful coworker or confident liar?',desc:'Where AI saves time, where it makes things up, and how to tell the difference.',access:'free',duration:'32 min'},
 {id:'prompts',topic:'AI for Everyday Work',date:'2026-10-12',title:'Better prompts, plain English',desc:'No magic phrases—just enough context to make AI genuinely useful.',access:'member',duration:'29 min'}
];
const h=(s,...v)=>s.reduce((a,x,i)=>a+x+(v[i]??''),'');
function setTheme(){document.body.classList.toggle('dark',state.theme==='dark');document.querySelector('#theme-toggle').textContent=state.theme==='dark'?'Light mode':'Dark mode'}
function updateSession(){const signed=state.role!=='visitor';document.querySelector('#signin-button').classList.toggle('hidden',signed);document.querySelector('#signup-button').classList.toggle('hidden',signed);document.querySelector('#signout-button').classList.toggle('hidden',!signed)}
function sessionBar(){return state.role==='visitor'?'':`<div class="session-bar">Demo session: ${state.role==='admin'?'Admin':'Subscriber'} · Help now shows ${state.role==='admin'?'admin':'subscriber'} guidance.</div>`}
function home(){return h`<section class="hero"><div><span class="kicker">Tech talk without the tech headache</span><h1>Serious tech.<br><span class="yellow">For the rest of us.</span></h1><p class="hero-copy">Relaxed conversations that turn complicated technology into useful ideas anyone can understand—and maybe laugh at along the way.</p><div class="button-row"><button class="button button-primary" data-play="ai-latest">Play Latest Episode</button><button class="button button-outline" data-route="browse" style="color:white">Browse All Shows</button></div></div><article class="hero-card"><div class="hero-art"><span class="mic">🎙️</span></div><h2>“Wait… what does the cloud actually do?”</h2><p class="meta">Like TAC Podcast · Illustrative Episode 01 · 32 min</p></article></section><section id="audience" class="section"><div class="section-title"><div><span class="eyebrow">Made for curious learners</span><h2>Technical enough to be useful. Simple enough to enjoy.</h2></div><strong>Like TAC creates the podcasts—you enjoy them.</strong></div><div class="grid-3"><article class="card"><span class="tag">New to the technology</span><h3>Build a useful foundation</h3><p>For technical people approaching an unfamiliar platform, product, or configuration for the first time.</p><button class="button button-primary" data-route="browse">Browse Technical Topics</button></article><article class="card"><span class="tag">Beginner or nontechnical</span><h3>Learn without being talked down to</h3><p>Explore subjects such as AI through clear explanations, everyday examples, and relaxed conversation.</p><button class="button button-primary" data-play="ai-latest">Play a Free Episode</button></article><article class="card dark-card"><span class="tag">Free Membership</span><h3>Come back whenever you’re curious</h3><p>Sign up to watch the complete archive and download audio or video episodes for later.</p><button class="button button-primary" data-route="signup">Subscribe Free</button></article></div></section>`}
function browse(){const topics=[...new Set(episodes.map(e=>e.topic))];return `<section class="section"><span class="eyebrow">Browse all shows</span><h1>Find your next “Oh, now I get it.”</h1><p class="lead">Browse every subject and publication date. Current and Start Here episodes are free. Archive episodes show a 45-second muted loop; click one to sign up or sign in.</p><div class="controls"><input class="input" id="search" placeholder="Search subjects or episodes"><select id="topic-filter"><option>All subjects</option>${topics.map(t=>`<option>${t}</option>`).join('')}</select><select id="sort"><option value="new">Newest first</option><option value="old">Oldest first</option></select></div><div id="catalog">${catalog(topics)}</div><p class="prototype-note">Episode names, dates, descriptions, and media are illustrative mock content.</p></section>`}
function catalog(topics){return topics.map(t=>`<section class="topic" data-topic="${t}"><div class="topic-head"><div><span class="eyebrow">Subject collection</span><h2>${t}</h2></div><span>${episodes.filter(e=>e.topic===t).length} episodes</span></div><div class="episode-grid">${episodes.filter(e=>e.topic===t).sort((a,b)=>b.date.localeCompare(a.date)).map(episodeCard).join('')}</div></section>`).join('')+`<section class="topic"><div class="topic-head"><div><span class="eyebrow">New category</span><h2>Network Automation</h2></div></div><div class="empty-category"><span class="tag">Coming Soon</span><h3>Fresh conversations are being planned.</h3><p>Check back soon for the first Like TAC episode in this subject.</p></div></section>`}
function episodeCard(e){const unlocked=e.access==='free'||state.role!=='visitor';return `<article class="episode-card" data-search="${(e.topic+' '+e.title).toLowerCase()}" data-date="${e.date}"><div class="episode-art"><span class="status-label">${e.access==='free'?'Free episode':unlocked?'Member access':'45-sec teaser'}</span><button aria-label="${unlocked?'Play':'Open teaser for'} ${e.title}" data-${unlocked?'play':'teaser'}="${e.id}">▶</button></div><div class="episode-content"><span class="eyebrow">${new Date(e.date+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})} · ${e.duration}</span><h3>${e.title}</h3><p>${e.desc}</p><div class="button-row">${unlocked?`<button class="button button-primary" data-play="${e.id}">Play</button><button class="button button-outline" data-download="${e.id}">Download</button>`:`<button class="button button-outline" data-teaser="${e.id}">Preview 45 sec</button><button class="button button-dark" data-gated="${e.id}">Watch Full Episode</button>`}</div></div></article>`}
function signup(){return `<section class="section"><span class="eyebrow">Free Like TAC membership</span><h1>Join the conversation—no jargon required.</h1><div class="form-layout"><form id="signup-form" class="form-card"><h2>Create your free account</h2><div class="account-switch">Already subscribed? <a href="#login">Sign in here</a> and we’ll return you to the episode you selected.</div><div class="field-row"><div class="field"><label>First name<input class="input" required></label></div><div class="field"><label>Last name<input class="input" required></label></div></div><div class="field"><label>Pronouns <span class="meta">(optional)</span><input class="input"></label></div><div class="field"><label>Email address<input class="input" type="email" required></label></div><div class="field"><label>Username<input class="input" required></label></div><div class="field-row"><div class="field"><label>Password<input class="input" type="password" pattern="(?=.*[a-z])(?=.*[A-Z])(?=.*\\d)(?=.*[!@*#]).{8,}" required></label></div><div class="field"><label>Confirm password<input class="input" type="password" required></label></div></div><label class="check"><input type="checkbox" required><span>I agree to receive Like TAC podcast announcements and newsletters. I can unsubscribe at any time.</span></label><button class="button button-primary button-wide">Create Free Account</button></form><aside class="form-card"><div class="rules"><h3>Password rules</h3><ul><li>At least 8 characters</li><li>Uppercase and lowercase letters</li><li>At least one number</li><li>At least one of: <strong>! @ * #</strong></li></ul></div><p>Like TAC stores secure hashes—not readable passwords.</p></aside></div></section>`}
function login(){return `<section class="section"><span class="eyebrow">Welcome back</span><h1>Choose a demo login.</h1><p class="lead">This prototype does not use real credentials. Choose a role to test role-aware navigation and Help.</p><div class="grid-3"><article class="card"><h2>Subscriber</h2><p>Unlock archive playback, downloads, and subscriber Help.</p><button class="button button-primary" data-demo-login="subscriber">Demo Subscriber Login</button></article><article class="card dark-card"><h2>Admin</h2><p>Continue to the branded email MFA check before opening protected tools.</p><button class="button button-primary" data-demo-login="admin">Demo Admin Login</button></article><article class="card"><h2>Account Help</h2><p>Recover a username or use the detailed temporary-password reset flow.</p><div class="button-row"><button class="button button-outline" data-route="forgot-username">Forgot Username</button><button class="button button-outline" data-route="forgot-password">Forgot Password</button></div></article></div></section>`}
function forgot(kind){return `<section class="section"><span class="eyebrow">Account recovery</span><h1>${kind==='username'?'Forgot your username?':'Reset your password'}</h1><div class="form-layout"><form class="form-card recovery-form"><div class="field"><label>Verified email address<input class="input" type="email" required></label></div><button class="button button-primary">Send ${kind==='username'?'Username Reminder':'Reset Instructions'}</button></form><aside class="form-card"><h2>What happens next</h2>${kind==='username'?'<p>We send the account username to the verified email without revealing on this page whether an account exists.</p>':'<ol class="steps"><li>Open the short-lived reset link in your email.</li><li>Enter the one-time temporary password from the email.</li><li>Create and confirm a new permanent password.</li><li>Sign in again on every device.</li></ol><p>The permanent password must meet all rules and cannot match the previous five passwords.</p>'}</aside></div></section>`}
function audience(){return `<section class="section"><span class="eyebrow">Who Like TAC is for</span><h1>Come curious. Leave understanding more.</h1><p class="lead">Like TAC is a listening and viewing portal for technical newcomers, beginners, and nontechnical learners. Like TAC’s podcasters create the content and explain complex subjects in clear, simple terms.</p><div class="grid-3"><article class="card"><span class="tag">Technical newcomer</span><h3>New technology, familiar feeling</h3><p>Get oriented before a deployment, configuration, class, or first hands-on project.</p></article><article class="card"><span class="tag">Nontechnical learner</span><h3>Understand the idea first</h3><p>Learn what technologies such as AI mean, what they can do, and why they matter—without acronym overload.</p></article><article class="card dark-card"><span class="tag">Relaxed delivery</span><h3>Easy language, real examples</h3><p>Our podcasters use stories, analogies, and conversation to make technical topics approachable.</p><button class="button button-primary" data-route="browse">Browse All Shows</button></article></div></section>`}
function help(){return state.role==='admin'?adminHelp():subscriberHelp()}
function subscriberHelp(){return `<section class="section"><span class="eyebrow">Help for listeners</span><h1>Enjoy Like TAC without wrestling the website.</h1><div class="help-grid"><nav class="help-nav" aria-label="Help topics"><a href="#help-play">Play episodes</a><a href="#help-download">Download</a><a href="#help-apps">Playback apps</a><a href="#help-account">Account help</a><a href="#help-access">Accessibility</a></nav><div class="help-content"><article id="help-play" class="card"><h2>Find and play an episode</h2><ol class="steps"><li>Choose Browse Shows.</li><li>Search or select a subject.</li><li>Play a free episode or sign in to unlock the archive.</li></ol></article><article id="help-download" class="card"><h2>Download for offline playback</h2><ol class="steps"><li>Sign in as a free subscriber.</li><li>Open the episode and choose Download.</li><li>Select audio or video when both are available.</li><li>Find the file in your device’s Downloads folder.</li></ol><div class="download-box">Typical files: audio <code>.mp3</code> · video <code>.mp4</code></div></article><article id="help-apps" class="card"><h2>Apps that usually play downloads</h2><p>Modern browsers can play streams directly. Downloaded MP3 and MP4 files normally open in Windows Media Player, Apple Music/QuickTime, VLC, or your phone’s built-in media player. VLC is a useful free fallback for uncommon playback problems.</p></article><article id="help-account" class="card"><h2>Account and password help</h2><p>Use Forgot Username or Forgot Password on the Sign In page. Password-reset emails explain every step, code expiration, and password rule.</p><button class="button button-outline" data-route="login">Open Sign In Help</button></article><article id="help-access" class="card"><h2>Captions, transcripts, and display</h2><p>Use captions when available, download transcripts, switch light/dark mode, and control teaser audio with the mute button.</p></article></div></div></section>`}
function adminHelp(){return `<section class="section"><span class="eyebrow">Protected admin help</span><h1>Manage Like TAC with confidence.</h1><div class="help-grid"><nav class="help-nav"><a href="#admin-content">Podcast content</a><a href="#admin-category">Categories</a><a href="#admin-users">Subscribers</a><a href="#admin-vercel">Vercel</a><a href="#admin-security">Security</a></nav><div class="help-content"><article id="admin-content" class="card"><h2>Upload and manage podcasts</h2><ol class="steps"><li>Open Admin Dashboard → Upload Podcast.</li><li>Add title, subject, summary, date, audio/video, teaser, captions, and access level.</li><li>Save as Draft and preview every control.</li><li>Publish when the episode is ready.</li></ol></article><article id="admin-category" class="card"><h2>Create and manage categories</h2><p>Create a clear subject name, optional description, and display order. A category with no published content remains visible as:</p><div class="empty-category"><span class="tag">Coming Soon</span><h3>Fresh conversations are being planned.</h3><p>Check back soon for the first Like TAC episode in this subject.</p></div></article><article id="admin-users" class="card"><h2>Manage subscribers in Like TAC</h2><p>Use the protected Subscribers area to search accounts, review consent status, disable access, or assist with recovery. Subscriber passwords remain unreadable.</p><button class="button button-primary" data-route="admin">Open Admin Dashboard</button></article><article id="admin-vercel" class="card"><h2>What to manage in Vercel</h2><p>Use Vercel for deployments, custom domain settings for <strong>liketac.live</strong>, environment variables, logs, observability, and rollbacks. Do not use Vercel as the subscriber-management screen; Like TAC account data belongs in Neon and is administered through this site.</p></article><article id="admin-security" class="card"><h2>Admin security</h2><p>MFA is required unless a private device was verified within the past 30 days. Profile, email, password, and security history remain separate from subscriber recovery.</p></article></div></div></section>`}
function admin(){return `<section class="section"><span class="eyebrow">Protected administration</span><h1>Podcast dashboard</h1><div class="admin-layout"><aside class="admin-menu"><button data-toast="Opening upload form">Upload Podcast</button><button data-toast="Opening episode library">Podcast Library</button><button data-toast="Opening category manager">Categories</button><button data-toast="Opening subscriber manager">Subscribers</button><button data-route="admin-profile">Admin Profile</button><button data-route="help">Admin Help</button></aside><div><div class="admin-stats"><article class="card stat"><strong>24</strong><span>Published</span></article><article class="card stat"><strong>3</strong><span>Drafts</span></article><article class="card stat"><strong>8</strong><span>Categories</span></article></div><article class="card" style="margin-top:16px"><div class="section-title"><h2>Recent episodes</h2><button class="button button-primary" data-toast="Opening upload form">Upload Podcast</button></div><table class="table"><thead><tr><th>Episode</th><th>Category</th><th>Status</th><th></th></tr></thead><tbody><tr><td>Expressway without the acronym soup</td><td>Expressway</td><td>Published</td><td><button class="button button-outline" data-toast="Opening episode editor">Edit</button></td></tr><tr><td>Certificates, DNS, and the usual suspects</td><td>Expressway</td><td>Draft</td><td><button class="button button-outline" data-toast="Opening episode editor">Edit</button></td></tr></tbody></table></article></div></div></section>`}
function adminProfile(){return `<section class="section"><span class="eyebrow">Private admin profile</span><h1>Administrator information</h1><form class="form-card profile-form"><div class="field-row"><div class="field"><label>First name<input class="input"></label></div><div class="field"><label>Last name<input class="input"></label></div></div><div class="field"><label>Pronouns<input class="input"></label></div><div class="field"><label>Street address<input class="input"></label></div><div class="field-row"><div class="field"><label>City<input class="input"></label></div><div class="field"><label>State / postal code<input class="input"></label></div></div><div class="field-row"><div class="field"><label>Phone<input class="input" type="tel"></label></div><div class="field"><label>Security email<input class="input" type="email" value="jjanson10@gmail.com"></label></div></div><div class="notice">Sensitive changes require password confirmation and generate a security notification.</div><button class="button button-primary" style="margin-top:16px">Save Protected Profile</button></form></section>`}
function privacy(){return `<section class="section"><span class="eyebrow">Prototype policy outline</span><h1>Privacy</h1><div class="card"><p>The production policy will explain account information, communications consent, playback/download records, security logs, retention, cancellation, and contact choices before launch. This mockup does not collect or send real data.</p></div></section>`}
const routes={home,browse,signup,login,audience,help,admin,'admin-profile':adminProfile,privacy,'forgot-username':()=>forgot('username'),'forgot-password':()=>forgot('password')};
function route(){let key=location.hash.slice(1)||'home';if((key==='admin'||key==='admin-profile')&&state.role!=='admin')key='login';main.innerHTML=sessionBar()+(routes[key]||home)();updateSession();bind();main.focus()}
function bind(){document.querySelectorAll('[data-route]').forEach(el=>el.onclick=()=>{const r=el.dataset.route;if(r==='signup'&&document.querySelector('#teaser-dialog')?.open)document.querySelector('#teaser-dialog').close();location.hash=r});document.querySelectorAll('[data-play]').forEach(el=>el.onclick=()=>openPlayer(el.dataset.play));document.querySelectorAll('[data-download]').forEach(el=>el.onclick=()=>toast(`Download started for ${find(el.dataset.download).title} (prototype only).`));document.querySelectorAll('[data-teaser]').forEach(el=>el.onclick=()=>openTeaser(el.dataset.teaser));document.querySelectorAll('[data-gated]').forEach(el=>el.onclick=()=>{state.returnTo='browse';location.hash='signup'});document.querySelectorAll('[data-demo-login]').forEach(el=>el.onclick=()=>loginAs(el.dataset.demoLogin));document.querySelectorAll('[data-toast]').forEach(el=>el.onclick=()=>toast(el.dataset.toast));document.querySelectorAll('.recovery-form').forEach(f=>f.onsubmit=e=>{e.preventDefault();toast('Recovery instructions sent in this prototype.')});document.querySelectorAll('.profile-form').forEach(f=>f.onsubmit=e=>{e.preventDefault();toast('Protected profile saved in this prototype.')});document.querySelector('#signup-form')?.addEventListener('submit',e=>{e.preventDefault();state.role='subscriber';sessionStorage.setItem('likeTacRole',state.role);toast('Free subscriber account created in demo mode.');location.hash=state.returnTo||'browse'});const search=document.querySelector('#search'),filter=document.querySelector('#topic-filter'),sort=document.querySelector('#sort');if(search)search.oninput=filterCatalog;if(filter)filter.onchange=filterCatalog;if(sort)sort.onchange=sortCatalog}
function find(id){return episodes.find(e=>e.id===id)}
function openTeaser(id){const e=find(id);state.returnTo='browse';document.querySelector('#teaser-title').textContent=e.title;document.querySelector('#teaser-dialog').showModal()}
function openPlayer(id){const e=find(id);document.querySelector('#player-title').textContent=e.title;document.querySelector('#player-status').textContent=`Playing ${e.duration} episode · prototype simulation`;document.querySelector('#player-pause').textContent='Pause';document.querySelector('#player-audio').textContent='Mute';document.querySelector('#player-dialog').showModal()}
function loginAs(role){if(role==='admin'){document.querySelector('#mfa-code').value='';document.querySelector('#mfa-dialog').showModal()}else{state.role='subscriber';sessionStorage.setItem('likeTacRole',state.role);location.hash=state.returnTo||'browse';route();toast('Signed in as a demo subscriber.')}}
function filterCatalog(){const q=document.querySelector('#search').value.toLowerCase(),t=document.querySelector('#topic-filter').value;document.querySelectorAll('.topic').forEach(section=>{if(!section.dataset.topic)return;let visible=0;section.querySelectorAll('.episode-card').forEach(card=>{const ok=(t==='All subjects'||section.dataset.topic===t)&&card.dataset.search.includes(q);card.hidden=!ok;if(ok)visible++});section.hidden=!visible})}
function sortCatalog(){const old=document.querySelector('#sort').value==='old';document.querySelectorAll('.episode-grid').forEach(g=>[...g.children].sort((a,b)=>old?a.dataset.date.localeCompare(b.dataset.date):b.dataset.date.localeCompare(a.dataset.date)).forEach(c=>g.append(c)))}
function toast(msg){const el=document.querySelector('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('show'),2600)}
document.addEventListener('click',e=>{if(e.target.matches('[data-close]'))e.target.closest('dialog').close()});
document.querySelector('#teaser-mute').onclick=e=>e.target.textContent=e.target.textContent==='Unmute'?'Mute':'Unmute';
document.querySelector('#player-pause').onclick=e=>e.target.textContent=e.target.textContent==='Pause'?'Play':'Pause';
document.querySelector('#player-audio').onclick=e=>e.target.textContent=e.target.textContent==='Mute'?'Unmute':'Mute';
document.querySelector('#player-fullscreen').onclick=async()=>{const stage=document.querySelector('#player-stage');if(!document.fullscreenElement){await stage.requestFullscreen()}else{await document.exitFullscreen()}};
document.addEventListener('fullscreenchange',()=>{document.querySelector('#player-fullscreen').textContent=document.fullscreenElement?'Exit Full Screen':'Full Screen'});
document.querySelector('#mfa-form').onsubmit=e=>{e.preventDefault();if(!/^\d{6}$/.test(document.querySelector('#mfa-code').value)){toast('Enter a six-digit code.');return}state.role='admin';sessionStorage.setItem('likeTacRole',state.role);document.querySelector('#mfa-dialog').close();location.hash='admin';route();toast('Admin identity verified. Device trust is simulated.')};
document.querySelector('#resend-mfa').onclick=()=>toast('A new six-digit code was sent in this prototype.');
document.querySelector('#theme-toggle').onclick=()=>{state.theme=state.theme==='dark'?'light':'dark';localStorage.setItem('likeTacTheme',state.theme);setTheme()};
document.querySelector('#signout-button').onclick=()=>{state.role='visitor';sessionStorage.removeItem('likeTacRole');location.hash='home';route();toast('Signed out of the demo session.')};
document.querySelector('#mobile-menu').onclick=e=>{const nav=document.querySelector('#nav');nav.classList.toggle('open');e.target.setAttribute('aria-expanded',nav.classList.contains('open'))};
window.addEventListener('hashchange',route);setTheme();route();
